const PT_PER_MM = 1 / 0.3528;  // ≈ 2.8346  (1pt = 0.3528mm)

// Color palette for SVG output
const SVG_OPERATION_ENGRAVE = 'engrave';
const SVG_OPERATION_CUT_RETAINED = 'cut-retained';
