/* Default fixture dimensions for a given style, mirroring getWindowDims().
 * Used by the toolbox card and editor when no custom size has been set. */
function getFixtureDims(styleKey) {
  const s = FIXTURE_STYLES[styleKey];
  if (!s) return { w: 4, h: 4 };
  return { w: s.width, h: s.height };
}

/* Build the inline SVG body for a fixture preview. Mirrors
 * buildDoorSvgBody / buildWindowSvgBody. Renders each piece bottom-to-top
 * (lower z-order first) with its own fill, stroke, and etched features.
 * Output coordinates are in target units; caller wraps in <svg viewBox> or
 * <g transform> as needed.
 */
function buildFixtureSvgBody(style, w, h, opts) {
  if (!style || !style.pieces || !style.pieces.length) return '';
  opts = opts || {};
  // Etched fixtures don't have visible piece bodies — they're pure engraving
  // on the cladding. The features ARE the visual, so skip body shapes and
  // only render features.
  const isEtched = style.placement === 'etched';
  const sx = w / style.width, sy = h / style.height;
  const sw       = (opts.strokeWidth      != null) ? opts.strokeWidth      : 0.18;
  const swThick  = (opts.thickStrokeWidth != null) ? opts.thickStrokeWidth : 0.3;
  let svg = '';

  for (const piece of style.pieces) {
    const px = (piece.offsetX != null) ? piece.offsetX : 0;
    const py = (piece.offsetY != null) ? piece.offsetY : 0;
    const pw = (piece.width  != null) ? piece.width  : style.width  - px;
    const ph = (piece.height != null) ? piece.height : style.height - py;
    const fill   = piece.panelFill  || '#bdbdb5';
    const stroke = piece.frameColor || '#3a3a34';

    // 1. Piece body (skipped for etched fixtures)
    if (!isEtched) {
      if (piece.shape === 'circle') {
        const cx = (px + pw / 2) * sx;
        const cy = (py + ph / 2) * sy;
        const r  = (pw / 2) * Math.min(sx, sy);
        svg += `<circle cx="${cx.toFixed(2)}" cy="${cy.toFixed(2)}" r="${r.toFixed(2)}"`
             + ` fill="${fill}" stroke="${stroke}" stroke-width="${sw.toFixed(3)}"/>`;
      } else {
        svg += `<rect x="${(px * sx).toFixed(2)}" y="${(py * sy).toFixed(2)}"`
             + ` width="${(pw * sx).toFixed(2)}" height="${(ph * sy).toFixed(2)}"`
             + ` fill="${fill}" stroke="${stroke}" stroke-width="${sw.toFixed(3)}"/>`;
      }
    }

    // Optional internal cut preview, used by rings/flanges. In the physical
    // fixture sheet this becomes an actual cut path; here it is shown as a
    // dark/empty hole so the toolbox/editor icon matches the part.
    if (!isEtched && piece.innerCut) {
      const ic = piece.innerCut;
      const ix = px + ((ic.x != null) ? ic.x : ((ic.xRatio || 0) * pw));
      const iy = py + ((ic.y != null) ? ic.y : ((ic.yRatio || 0) * ph));
      const iw = (ic.w != null) ? ic.w : ((ic.wRatio || 0.5) * pw);
      const ih = (ic.h != null) ? ic.h : ((ic.hRatio || 0.5) * ph);
      if (ic.shape === 'circle') {
        const cx = (ix + iw / 2) * sx;
        const cy = (iy + ih / 2) * sy;
        const r  = Math.min(iw * sx, ih * sy) / 2;
        svg += `<circle cx="${cx.toFixed(2)}" cy="${cy.toFixed(2)}" r="${r.toFixed(2)}" fill="#1a1814" stroke="${stroke}" stroke-width="${sw.toFixed(3)}"/>`;
      } else {
        svg += `<rect x="${(ix * sx).toFixed(2)}" y="${(iy * sy).toFixed(2)}" width="${(iw * sx).toFixed(2)}" height="${(ih * sy).toFixed(2)}" fill="#1a1814" stroke="${stroke}" stroke-width="${sw.toFixed(3)}"/>`;
      }
    }

    // 2. Etched features on this piece (coords in piece-local space).
    // featureGenerator(pw, ph) lets pieces produce density-adaptive etches —
    // bracket bands on a tall downspout, louvers on a wide vent, stacked
    // panels on a long banner. Static `features` are used when the etched
    // detail scales naturally with linear stretch.
    const pieceFeatures = piece.featureGenerator
      ? piece.featureGenerator(pw, ph)
      : (piece.features || []);
    if (pieceFeatures.length) {
      // Reuse doorFeatureShapes to expand the feature list — same vocabulary
      // (rail, panel, stud, ironBand, latticeVertical, horizontalRails…).
      const shapes = doorFeatureShapes({ width: pw, height: ph, features: pieceFeatures });
      if (shapes.length) {
        // Transform from piece-local mm to target SVG units, anchored at
        // the piece's top-left corner.
        const tx = (px * sx).toFixed(2), ty = (py * sy).toFixed(2);
        const scX = sx.toFixed(4),       scY = sy.toFixed(4);
        svg += `<g transform="translate(${tx} ${ty}) scale(${scX} ${scY})">`;
        svg += emitDoorShapesSvg(shapes, 0, 0, 1, {
          stroke: stroke,
          knobFill: stroke,
          strokeWidth: sw,
          thickStrokeWidth: swThick,
          pointerEvents: opts.pointerEvents,
        });
        svg += `</g>`;
      }
    }
  }
  return svg;
}

/* ===== js/00-13-window-feature-shapes.js ===== */
'use strict';

/* =====================================================================
   WINDOW FEATURE SHAPES
   Mirrors the door system: WINDOW_STYLES carries semantic data (mullion type,
   colours); windowFeatureShapes() turns that into low-level geometric
   primitives ({type:'line'|'rect'|...}); emitWindowShapesSvg() renders them
   inline; the laser-output generator uses the same primitives to drive etches
   and cuts on the frame piece. One data source, three consumers — the
   toolbox icon, the editor canvas, and the physical frame stay in sync.
   ===================================================================== */

/* Cell-count helpers — picked from window dimensions so the lattice adapts
 * to custom-sized windows. Returns at least the minimum count. */
function _renjiBarCount(W) {
  // bars ~0.4mm thick with ~0.5mm gap → 0.9mm pitch, 0.5mm end margin each side
  return Math.max(3, Math.min(12, Math.floor((W - 1.0) / 0.9)));
}
function _ranmaBarCount(W) {
  // ranma bars are slightly more spread out (~1.0mm pitch)
  return Math.max(5, Math.min(24, Math.floor((W - 1.0) / 1.0)));
}
function _mushikoSlitCount(W) {
  // Slits are 1.0mm wide with ≥1.2mm plaster between (kerf-safe).
  // Total = N*1.0 + (N+1)*1.2 ≤ W  ⇒  N ≤ (W-1.2)/2.2
  return Math.max(2, Math.floor((W - 1.2) / 2.2));
}
function _shojiCellCount(W, H) {
  return {
    cols: Math.max(2, Math.round(W / 2.7)),
    rows: Math.max(2, Math.round(H / 2.7)),
  };
}

/* Returns an array of {type, ...} primitives describing the visible lattice /
 * bars / kumiko etched on the window's external frame piece. Coordinates are
 * in window-local mm, origin at top-left of the visible aperture.
 *
 *   line   → {type:'line', x1, y1, x2, y2, thick?}
 *   rect   → {type:'rect', x, y, w, h, tint?}      (etched outline)
 *
 * NOTE: mushiko_slits are NOT returned here — they're real cut-throughs and
 * are handled by panesForMullion in layoutDividerFrame.
 */
function windowFeatureShapes(spec, W, H) {
  if (!spec || !spec.mullion) return [];
  const out = [];
  const m = spec.mullion;

  if (m === 'renji_vertical') {
    // Vertical wooden bars, etched. Bars sit just inside the frame edge.
    const n = _renjiBarCount(W);
    const inset = 0.5;
    const usable = W - inset * 2;
    const pitch  = usable / (n + 1);
    for (let i = 1; i <= n; i++) {
      const x = inset + i * pitch;
      out.push({ type: 'line', x1: x, y1: 0.3, x2: x, y2: H - 0.3, thick: true });
    }
    return out;
  }

  if (m === 'ranma_lattice') {
    // Like renji_vertical but tighter spacing for transom proportions.
    const n = _ranmaBarCount(W);
    const inset = 0.4;
    const usable = W - inset * 2;
    const pitch  = usable / (n + 1);
    for (let i = 1; i <= n; i++) {
      const x = inset + i * pitch;
      out.push({ type: 'line', x1: x, y1: 0.25, x2: x, y2: H - 0.25 });
    }
    return out;
  }

  if (m === 'shoji_grid') {
    // Fine kumiko grid — cell count picked from W & H.
    const { cols, rows } = _shojiCellCount(W, H);
    const inset = 0.25;
    const usableW = W - inset * 2, usableH = H - inset * 2;
    // Vertical kumiko (between columns)
    for (let c = 1; c < cols; c++) {
      const x = inset + (c / cols) * usableW;
      out.push({ type: 'line', x1: x, y1: inset, x2: x, y2: H - inset });
    }
    // Horizontal kumiko
    for (let r = 1; r < rows; r++) {
      const y = inset + (r / rows) * usableH;
      out.push({ type: 'line', x1: inset, y1: y, x2: W - inset, y2: y });
    }
    return out;
  }

  if (m === 'yukimi_split') {
    // Top half = shoji kumiko (etched), bottom half = clear pane (no etching).
    // A thicker horizontal "meeting rail" line marks the split.
    const splitY = H * 0.55;
    const inset = 0.25;
    const usableW = W - inset * 2;
    const usableH = splitY - inset;
    // Meeting rail (thicker etch line)
    out.push({ type: 'line', x1: 0, y1: splitY, x2: W, y2: splitY, thick: true });
    // Kumiko in the top half — generator picks counts based on top-half size
    const { cols, rows } = _shojiCellCount(W, splitY);
    for (let c = 1; c < cols; c++) {
      const x = inset + (c / cols) * usableW;
      out.push({ type: 'line', x1: x, y1: inset, x2: x, y2: splitY });
    }
    for (let r = 1; r < rows; r++) {
      const y = inset + (r / rows) * usableH;
      out.push({ type: 'line', x1: inset, y1: y, x2: W - inset, y2: y });
    }
    return out;
  }

  // Other mullion types (vertical_1, grid_2x2, etc.) — no etched features;
  // their mullion bars are real retained material in the divider frame.
  return [];
}

/** Emit SVG markup for window-local shapes. Mirrors emitDoorShapesSvg.
 *  `s` is the input→output unit scale. `ox/oy` translate origin. */
function emitWindowShapesSvg(shapes, ox, oy, s, opts) {
  opts = opts || {};
  const stroke  = opts.stroke      || '#2a64aa';
  const sw      = (opts.strokeWidth      != null) ? opts.strokeWidth      : 0.18;
  const swThick = (opts.thickStrokeWidth != null) ? opts.thickStrokeWidth : sw * 1.8;
  const pe      = opts.pointerEvents ? '' : ' pointer-events="none"';

  let svg = '';
  for (const sh of shapes) {
    if (sh.type === 'line') {
      const x1 = (ox + sh.x1 * s).toFixed(2);
      const y1 = (oy + sh.y1 * s).toFixed(2);
      const x2 = (ox + sh.x2 * s).toFixed(2);
      const y2 = (oy + sh.y2 * s).toFixed(2);
      const w  = sh.thick ? swThick : sw;
      svg += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${stroke}" stroke-width="${w}" stroke-linecap="square"${pe}/>`;
    } else if (sh.type === 'rect') {
      const x = (ox + sh.x * s).toFixed(2);
      const y = (oy + sh.y * s).toFixed(2);
      const w = (sh.w * s).toFixed(2);
      const h = (sh.h * s).toFixed(2);
      const fill = sh.tint ? (opts.tintFill || 'rgba(0,0,0,0.18)') : 'none';
      svg += `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"${pe}/>`;
    }
  }
  return svg;
}

/* For mushiko_mado, slit rects are real cut-throughs (not etches). This
 * helper computes their geometry (window-local coords, inset from frame edge)
 * so the toolbox preview, editor canvas, and laser-output plaster frame all
 * agree on where the slits are. */
function mushikoSlitRects(W, H) {
  const n = _mushikoSlitCount(W);
  const slitW = 1.0;
  const gap = (W - n * slitW) / (n + 1);
  const inset = Math.max(0.5, H * 0.18);  // top/bottom plaster margin
  const slitH = H - inset * 2;
  const out = [];
  for (let i = 0; i < n; i++) {
    out.push({
      x: gap + i * (slitW + gap),
      y: inset,
      w: slitW,
      h: slitH,
    });
  }
  return out;
}

/* Build the inline SVG body for a window preview. Used by the toolbox card
 * and the editor canvas so both show the actual visual pattern. The same
 * three sources of geometric truth are consulted as for the laser output:
 *   - style.mullion=mushiko_slits → slit rects via mushikoSlitRects()
 *   - style.mullion=yukimi_split  → top paper + bottom clear glass
 *   - other Japanese lattices     → windowFeatureShapes() (etched lines)
 *   - Western mullions            → drawn as thick lines (retained material
 *                                   in the divider frame at laser time)
 * Output coordinates use the spec's mm units (caller wraps in viewBox or
 * <g transform> as needed).
 */
function buildWindowSvgBody(style, w, h, opts) {
  opts = opts || {};
  const frameColor = (style && style.frameColor) || (opts.stroke || '#2a64aa');
  const paneFill   = (style && style.paneFill)   || 'rgba(160,205,245,0.85)';
  const sw         = (opts.strokeWidth != null) ? opts.strokeWidth : 0.3;
  const swThick    = sw * 1.6;
  let svg = '';

  // --- Blanked variants: no real glass; show as painted/boarded panel ---
  if (style && (style.placement === 'etched' || style.placement === 'blanked')) {
    const isEtched = style.placement === 'etched';
    if (isEtched) {
      // Etched-on-cladding — no cut. Dashed outline + a faint sash cross to
      // show "this is a faux window, won't actually have an opening".
      svg += `<rect x="0.2" y="0.2" width="${(w-0.4).toFixed(2)}" height="${(h-0.4).toFixed(2)}"`
           + ` fill="rgba(60,55,48,0.18)" stroke="${frameColor}"`
           + ` stroke-width="${sw}" stroke-dasharray="0.8 0.5"/>`;
      if (w > 4 && h > 4) {
        svg += `<line x1="${(w/2).toFixed(2)}" y1="0.4" x2="${(w/2).toFixed(2)}" y2="${(h-0.4).toFixed(2)}"`
             + ` stroke="${frameColor}" stroke-width="${(sw*0.7).toFixed(3)}" stroke-dasharray="0.6 0.4"/>`;
        svg += `<line x1="0.4" y1="${(h/2).toFixed(2)}" x2="${(w-0.4).toFixed(2)}" y2="${(h/2).toFixed(2)}"`
             + ` stroke="${frameColor}" stroke-width="${(sw*0.7).toFixed(3)}" stroke-dasharray="0.6 0.4"/>`;
      }
    } else {
      // Blanked filled — solid opaque dark panel that fills the hole, no
      // transparency. Reads as boarded-up / bricked-in from outside.
      svg += `<rect x="0.2" y="0.2" width="${(w-0.4).toFixed(2)}" height="${(h-0.4).toFixed(2)}"`
           + ` fill="${paneFill}" stroke="${frameColor}" stroke-width="${sw}"/>`;
      // Subtle "boards" hint — a few horizontal etch lines
      const bandCount = Math.max(2, Math.min(5, Math.floor(h / 2.5)));
      for (let i = 1; i < bandCount; i++) {
        const y = (h * i / bandCount).toFixed(2);
        svg += `<line x1="0.4" y1="${y}" x2="${(w-0.4).toFixed(2)}" y2="${y}"`
             + ` stroke="rgba(0,0,0,0.25)" stroke-width="${(sw*0.5).toFixed(3)}"/>`;
      }
    }
    return svg;
  }

  // --- mushiko: plaster body with dark cut-through slits ---
  if (style && style.mullion === 'mushiko_slits') {
    svg += `<rect x="0.2" y="0.2" width="${(w-0.4).toFixed(2)}" height="${(h-0.4).toFixed(2)}"`
         + ` fill="${paneFill}" stroke="${frameColor}" stroke-width="${sw}"/>`;
    // Inner recess line
    const inX = Math.min(0.7, w * 0.07), inY = Math.min(0.5, h * 0.12);
    svg += `<rect x="${inX.toFixed(2)}" y="${inY.toFixed(2)}"`
         + ` width="${(w-inX*2).toFixed(2)}" height="${(h-inY*2).toFixed(2)}"`
         + ` fill="none" stroke="${frameColor}" stroke-width="${(sw*0.5).toFixed(3)}" opacity="0.6"/>`;
    for (const s of mushikoSlitRects(w, h)) {
      svg += `<rect x="${s.x.toFixed(2)}" y="${s.y.toFixed(2)}"`
           + ` width="${s.w.toFixed(2)}" height="${s.h.toFixed(2)}" fill="#3a3028"/>`;
    }
    return svg;
  }

  // --- yukimi: split (top paper-tinted, bottom clear glass) ---
  if (style && style.mullion === 'yukimi_split') {
    const splitY = h * 0.55;
    svg += `<rect x="0.2" y="0.2" width="${(w-0.4).toFixed(2)}" height="${(splitY-0.2).toFixed(2)}"`
         + ` fill="${paneFill}" stroke="${frameColor}" stroke-width="${sw}"/>`;
    svg += `<rect x="0.2" y="${splitY.toFixed(2)}" width="${(w-0.4).toFixed(2)}" height="${(h-splitY-0.2).toFixed(2)}"`
         + ` fill="rgba(160,205,245,0.85)" stroke="${frameColor}" stroke-width="${sw}"/>`;
    // Etched kumiko + meeting rail from the same shape source as the laser output
    const shapes = windowFeatureShapes(style, w, h);
    svg += emitWindowShapesSvg(shapes, 0, 0, 1, {
      stroke: frameColor, strokeWidth: sw * 0.6, thickStrokeWidth: swThick,
    });
    return svg;
  }

  // --- standard pane background ---
  svg += `<rect x="0.2" y="0.2" width="${(w-0.4).toFixed(2)}" height="${(h-0.4).toFixed(2)}"`
       + ` fill="${paneFill}" stroke="${frameColor}" stroke-width="${sw}"/>`;

  // --- Western mullions (retained material in divider frame at laser time;
  //     drawn here as thick lines so the preview matches the visible bars) ---
  if (style && style.mullion) {
    const m = style.mullion;
    if (m === 'vertical_1') {
      svg += `<line x1="${(w/2).toFixed(2)}" y1="0.3" x2="${(w/2).toFixed(2)}" y2="${(h-0.3).toFixed(2)}"`
           + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
    } else if (m === 'vertical_many') {
      const n = Math.max(3, Math.min(5, Math.floor(w / 6)));
      for (let i = 1; i < n; i++) {
        const x = (w / n) * i;
        svg += `<line x1="${x.toFixed(2)}" y1="0.3" x2="${x.toFixed(2)}" y2="${(h-0.3).toFixed(2)}"`
             + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
      }
    } else if (m === 'grid_2x2') {
      svg += `<line x1="${(w/2).toFixed(2)}" y1="0.3" x2="${(w/2).toFixed(2)}" y2="${(h-0.3).toFixed(2)}"`
           + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
      svg += `<line x1="0.3" y1="${(h/2).toFixed(2)}" x2="${(w-0.3).toFixed(2)}" y2="${(h/2).toFixed(2)}"`
           + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
    } else if (m === 'grid_3x2') {
      svg += `<line x1="${(w/3).toFixed(2)}" y1="0.3" x2="${(w/3).toFixed(2)}" y2="${(h-0.3).toFixed(2)}"`
           + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
      svg += `<line x1="${(2*w/3).toFixed(2)}" y1="0.3" x2="${(2*w/3).toFixed(2)}" y2="${(h-0.3).toFixed(2)}"`
           + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
      svg += `<line x1="0.3" y1="${(h/2).toFixed(2)}" x2="${(w-0.3).toFixed(2)}" y2="${(h/2).toFixed(2)}"`
           + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
    } else if (m === 'industrial_slider_3' || m === 'industrial_slider_4' || m === 'industrial_slider_6') {
      const cols = (m === 'industrial_slider_3') ? 3 : (m === 'industrial_slider_4') ? 4 : 6;
      for (let i = 1; i < cols; i++) {
        const x = (w / cols) * i;
        svg += `<line x1="${x.toFixed(2)}" y1="0.3" x2="${x.toFixed(2)}" y2="${(h-0.3).toFixed(2)}"`
             + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
      }
      const splitY = h * 0.68;
      svg += `<line x1="0.3" y1="${splitY.toFixed(2)}" x2="${(w-0.3).toFixed(2)}" y2="${splitY.toFixed(2)}"`
           + ` stroke="${frameColor}" stroke-width="${swThick}"/>`;
    }
  }

  // --- Japanese etched lattices (renji, ranma, shoji) ---
  const shapes = style ? windowFeatureShapes(style, w, h) : [];
  if (shapes.length) {
    svg += emitWindowShapesSvg(shapes, 0, 0, 1, {
      stroke: frameColor,
      strokeWidth: sw * 0.6,
      thickStrokeWidth: swThick * 0.8,
    });
  }

  return svg;
}

/* ===== js/00-14-shutter-styles-decorative-panels-flanking-a-window.js ===== */
'use strict';

/* =====================================================================
   SHUTTER STYLES — decorative panels flanking a window
   =====================================================================
   Each window opening can opt into a pair of shutters via the
   `hasShutters` + `shutterStyle` fields on its op. Shutters are NOT
   structural — they sit on top of the cladding next to the window like
   layered fixtures. Each window with shutters produces 2 identical cut
   pieces (one for each side); the laser sheets group by (style, size).

   Each entry provides:
     label, description — UI strings
     panelFill, frameColor — editor/preview hints
     featureGenerator(w, h) — etch primitives that adapt to actual size

   Shutter dimensions are derived from the window:
     shutterW = max(2, window.w * SHUTTER_W_RATIO)  // default ratio 0.5
     shutterH = window.h
*/
const SHUTTER_W_RATIO = 0.5;   // shutter width as fraction of window width

const SHUTTER_STYLES = {
  louvered: {
    label: 'Louvered',
    description: 'Classic colonial shutters with horizontal slats.',
    panelFill: '#5a3a22', frameColor: '#2a1808',
    featureGenerator: (w, h) => {
      const margin = 0.45;
      const targetPitch = 0.55;
      const usable = Math.max(0, h - 2 * margin);
      const count = Math.max(3, Math.round(usable / targetPitch));
      const pitch = usable / count;
      const out = [];
      for (let i = 0; i <= count; i++) {
        const y = margin + i * pitch;
        out.push({ type: 'rail', x1: 0.3, y1: y, x2: w - 0.3, y2: y });
      }
      return out;
    },
  },
  raised_panel: {
    label: 'Raised panel',
    description: 'Formal shutters with two stacked rectangular raised panels.',
    panelFill: '#6a4a2a', frameColor: '#2a1808',
    featureGenerator: (w, h) => {
      const inset = Math.max(0.3, Math.min(0.6, w * 0.08));
      const mid = h * 0.5;
      const gap = 0.25;
      return [
        // Upper panel
        { type: 'panel', x1: inset, y1: inset, x2: w - inset, y2: mid - gap },
        // Lower panel
        { type: 'panel', x1: inset, y1: mid + gap, x2: w - inset, y2: h - inset },
      ];
    },
  },
  board_batten: {
    label: 'Board & batten',
    description: 'Rustic vertical planks held together by horizontal battens (top, middle, bottom).',
    panelFill: '#7a5a3a', frameColor: '#3a2410',
    featureGenerator: (w, h) => {
      const out = [];
      // 3 vertical plank seams
      const boards = 3;
      for (let i = 1; i < boards; i++) {
        const x = (w / boards) * i;
        out.push({ type: 'rail', x1: x, y1: 0.2, x2: x, y2: h - 0.2 });
      }
      // 3 horizontal battens — top, middle, bottom (thicker stroke)
      const battenY = [0.7, h * 0.5, h - 0.7];
      for (const y of battenY) {
        out.push({ type: 'rail', x1: 0, y1: y, x2: w, y2: y, thick: true });
      }
      return out;
    },
  },
  cross_buck: {
    label: 'Cross-buck (Z-pattern)',
    description: 'Country style with a top rail, bottom rail, and a diagonal brace forming a Z.',
    panelFill: '#7a5a3a', frameColor: '#3a2410',
    featureGenerator: (w, h) => {
      const inset = 0.3;
      return [
        // Top rail
        { type: 'rail', x1: inset, y1: h * 0.22, x2: w - inset, y2: h * 0.22, thick: true },
        // Bottom rail
        { type: 'rail', x1: inset, y1: h * 0.78, x2: w - inset, y2: h * 0.78, thick: true },
        // Diagonal brace (from bottom-left to top-right)
        { type: 'rail', x1: inset, y1: h * 0.78, x2: w - inset, y2: h * 0.22, thick: true },
      ];
    },
  },
  plain: {
    label: 'Plain',
    description: 'Simple solid panel — minimalist or to be painted with custom decoration.',
    panelFill: '#5a3a22', frameColor: '#2a1808',
    featureGenerator: (w, h) => [],
  },
};

/* Build an inline SVG body for a shutter style at given dimensions. Used
 * by the topbar dropdown previews, the editor canvas, and (via shared
 * coords) the laser cut sheet. Mirrors buildFixtureSvgBody's pattern. */
function buildShutterSvgBody(style, w, h, opts) {
  if (!style) return '';
  opts = opts || {};
  const sw      = (opts.strokeWidth      != null) ? opts.strokeWidth      : 0.18;
  const swThick = (opts.thickStrokeWidth != null) ? opts.thickStrokeWidth : 0.3;
  const fill    = style.panelFill  || '#5a3a22';
  const stroke  = style.frameColor || '#2a1808';

  let svg = `<rect x="0" y="0" width="${w.toFixed(2)}" height="${h.toFixed(2)}"`
          + ` fill="${fill}" stroke="${stroke}" stroke-width="${sw.toFixed(3)}"/>`;
  const features = style.featureGenerator ? style.featureGenerator(w, h) : (style.features || []);
  if (features.length) {
    const shapes = doorFeatureShapes({ width: w, height: h, features });
    svg += emitDoorShapesSvg(shapes, 0, 0, 1, {
      stroke: stroke, knobFill: stroke,
      strokeWidth: sw, thickStrokeWidth: swThick,
      pointerEvents: opts.pointerEvents,
    });
  }
  return svg;
}

/* Compute shutter dimensions for a given window op. Returns null if the
 * window doesn't have shutters enabled or has invalid dimensions. */
function getShutterDimsForWindow(op) {
  if (!op || op.type !== 'window' || !op.hasShutters) return null;
  const w = Math.max(2, op.w * SHUTTER_W_RATIO);
  const h = op.h;
  return { w, h };
}

const EXTERIOR_LIGHT_SVG_W = 9.5;
const EXTERIOR_LIGHT_SVG_H = 8.09;
// Source SVG coordinate space is only used for proportions. Physical model
// defaults are explicit millimetres for N-scale laser cutting.
const EXTERIOR_LIGHT_DEFAULT_W = 3.0;
const EXTERIOR_LIGHT_DEFAULT_H = 2.5;
const EXTERIOR_LIGHT_WIRE_HOLE_D = 0.75;
const EXTERIOR_LIGHT_WIRE_HOLE_X = (EXTERIOR_LIGHT_DEFAULT_W - EXTERIOR_LIGHT_WIRE_HOLE_D) / 2;
const EXTERIOR_LIGHT_WIRE_HOLE_Y = EXTERIOR_LIGHT_DEFAULT_H * ((3.33 + 4.25 / 2) / EXTERIOR_LIGHT_SVG_H) - EXTERIOR_LIGHT_WIRE_HOLE_D / 2;

function exteriorLightRoundedCapPath(w, h, ox = 0, oy = 0) {
  const x0 = ox + w * (0.50 / EXTERIOR_LIGHT_SVG_W);
  const x1 = ox + w * (9.00 / EXTERIOR_LIGHT_SVG_W);
  const y0 = oy + h * (0.50 / EXTERIOR_LIGHT_SVG_H);
  const y1 = oy + h * (7.59 / EXTERIOR_LIGHT_SVG_H);
  const rX = w * (1.38 / EXTERIOR_LIGHT_SVG_W);
  const rY = h * (1.38 / EXTERIOR_LIGHT_SVG_H);
  return `M ${x1.toFixed(3)},${y1.toFixed(3)}`
    + ` V ${(y0 + rY).toFixed(3)}`
    + ` Q ${x1.toFixed(3)},${y0.toFixed(3)} ${(x1 - rX).toFixed(3)},${y0.toFixed(3)}`
    + ` H ${(x0 + rX).toFixed(3)}`
    + ` Q ${x0.toFixed(3)},${y0.toFixed(3)} ${x0.toFixed(3)},${(y0 + rY).toFixed(3)}`
    + ` V ${y1.toFixed(3)}`
    + ` H ${x1.toFixed(3)} Z`;
}

function exteriorLightCoreUPath(w, h, ox = 0, oy = 0) {
  const x0 = ox + w * (0.50 / EXTERIOR_LIGHT_SVG_W);
  const x1 = ox + w * (9.00 / EXTERIOR_LIGHT_SVG_W);
  const y0 = oy + h * (0.50 / EXTERIOR_LIGHT_SVG_H);
  const y1 = oy + h * (7.59 / EXTERIOR_LIGHT_SVG_H);
  const rX = w * (1.38 / EXTERIOR_LIGHT_SVG_W);
  const rY = h * (1.38 / EXTERIOR_LIGHT_SVG_H);
  const ix0 = ox + w * (3.33 / EXTERIOR_LIGHT_SVG_W);
  const ix1 = ox + w * (6.16 / EXTERIOR_LIGHT_SVG_W);
  const iy0 = oy + h * (3.33 / EXTERIOR_LIGHT_SVG_H);
  return `M ${(x1 - rX).toFixed(3)},${y0.toFixed(3)}`
    + ` H ${(x0 + rX).toFixed(3)}`
    + ` Q ${x0.toFixed(3)},${y0.toFixed(3)} ${x0.toFixed(3)},${(y0 + rY).toFixed(3)}`
    + ` V ${y1.toFixed(3)}`
    + ` H ${ix0.toFixed(3)}`
    + ` V ${iy0.toFixed(3)}`
    + ` H ${ix1.toFixed(3)}`
    + ` V ${y1.toFixed(3)}`
    + ` H ${x1.toFixed(3)}`
    + ` V ${(y0 + rY).toFixed(3)}`
    + ` Q ${x1.toFixed(3)},${y0.toFixed(3)} ${(x1 - rX).toFixed(3)},${y0.toFixed(3)} Z`;
}

/* Additional wall fixture catalog entries that are defined after the shared
 * feature vocabulary is available but before the editor/toolbox and fixture
 * part generator load. Kept as static source data; no DOM/runtime HTML patching.
 */
if (typeof FIXTURE_STYLES !== 'undefined') {
  FIXTURE_STYLES.exterior_light = {
    label: 'Exterior light',
    description: 'Wall light with a 0.75 mm circular pass-through for a pre-wired SMD LED. Exports a rounded-top core U-shaped spacer/cradle plus a matching filled cladding cap.',
    width: EXTERIOR_LIGHT_DEFAULT_W,
    height: EXTERIOR_LIGHT_DEFAULT_H,
    depthTier: 'medium',
    toolboxSection: 'passthroughs',
    throughCore: true,
    throughHole: {
      shape: 'circle',
      x: EXTERIOR_LIGHT_WIRE_HOLE_X,
      y: EXTERIOR_LIGHT_WIRE_HOLE_Y,
      w: EXTERIOR_LIGHT_WIRE_HOLE_D,
      h: EXTERIOR_LIGHT_WIRE_HOLE_D,
    },
    pieces: [
      {
        material: 'core',
        panelFill: '#cfcfc7',
        frameColor: '#4a4a44',
        pathGenerator: exteriorLightCoreUPath,
        features: [],
      },
      {
        material: 'cladding',
        panelFill: '#f2eee2',
        frameColor: '#5a5044',
        pathGenerator: exteriorLightRoundedCapPath,
        features: [],
      },
    ],
  };

  if (typeof STYLE_I18N_JA !== 'undefined') {
    STYLE_I18N_JA.FIXTURE_STYLES = STYLE_I18N_JA.FIXTURE_STYLES || {};
    STYLE_I18N_JA.FIXTURE_STYLES.exterior_light = {
      label: '外灯',
      description: '配線済みSMD LEDを通すための0.75mm丸穴を持つ壁面ライト。丸みのあるコア材の逆U字スペーサーと、同形状で中央が塞がった外装キャップを出力します。',
    };
  }
}

if (typeof buildFixtureSvgBody === 'function' && !buildFixtureSvgBody.__supportsPathPieces) {
  const baseBuildFixtureSvgBody = buildFixtureSvgBody;
  buildFixtureSvgBody = function buildFixtureSvgBodyWithPathPieces(style, w, h, opts) {
    if (!style || !Array.isArray(style.pieces) || !style.pieces.some(p => typeof p.pathGenerator === 'function')) {
      return baseBuildFixtureSvgBody(style, w, h, opts);
    }
    opts = opts || {};
    const sx = w / style.width;
    const sy = h / style.height;
    const sw = (opts.strokeWidth != null) ? opts.strokeWidth : 0.18;
    let svg = '';
    for (const piece of style.pieces) {
      const px = (piece.offsetX != null) ? piece.offsetX : 0;
      const py = (piece.offsetY != null) ? piece.offsetY : 0;
      const pw = (piece.width != null) ? piece.width : style.width - px;
      const ph = (piece.height != null) ? piece.height : style.height - py;
      const d = piece.pathGenerator(pw * sx, ph * sy, px * sx, py * sy);
      const fill = piece.panelFill || '#bdbdb5';
      const stroke = piece.frameColor || '#3a3a34';
      svg += `<path d="${d}" fill="${fill}" stroke="${stroke}" stroke-width="${sw.toFixed(3)}"/>`;
    }
    return svg;
  };
  buildFixtureSvgBody.__supportsPathPieces = true;
}

/* ===== js/00-15-printed-items-library.js ===== */
'use strict';

/* =====================================================================
   PRINTED ITEMS LIBRARY
   These items are NOT laser-cut. They get printed on paper (or sticker
   stock) on a regular inkjet/laser printer, hand-cut along crop marks,
   and glued onto the model by the user.

   Each entry defines:
     label, description     — UI strings
     width, height          — default size in mm
     designSvg(w, h)        — returns inline SVG for the printed design at
                              the given dimensions. Used in the toolbox
                              preview, editor canvas, 3D plate texture,
                              AND the printed-sheet output. One source of
                              truth for the artwork.
   ===================================================================== */
/* Original polygon/path bodies extracted from the supplied Buffer-Large.svg
 * and Buffer-Small.svg artwork files. The polygons are positioned in their
 * original Adobe Illustrator coordinates (bbox starts at the bb_x/bb_y noted
 * in each PRINTED_STYLES entry), and the designSvg function below transforms
 * them into the printed item's local 0..w × 0..h frame via a single
 * `transform="scale(sx,sy) translate(-bb_x,-bb_y)"` wrapper. CSS class
 * references in the source SVGs have already been resolved to explicit
 * fill attributes so the bodies stand alone without a <style> block. */
